import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第九卦 小畜 風天小畜 巽上乾下","description":"周易 - 第九卦 小畜 風天小畜 巽上乾下","frontmatter":{"title":"第九卦 小畜 風天小畜 巽上乾下","description":"周易 - 第九卦 小畜 風天小畜 巽上乾下"},"headers":[],"relativePath":"classics/zhouyi/010.md","filePath":"classics/zhouyi/010.md"}'),l={name:"classics/zhouyi/010.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="小畜" tabindex="-1">小畜 <a class="header-anchor" href="#小畜" aria-label="Permalink to “小畜”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。密雲不雨，自我西郊。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>小畜；柔得位，而上下應之，曰小畜。健而巽，剛中而志行，乃亨。密雲不雨，尚往也。自我西郊，施未行也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>風行天上，小畜；君子以懿文德。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>復自道，何其咎，吉。象曰：復自道， 其義吉也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>牽復，吉。象曰：牽覆在中，亦不自失也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>輿說輻，夫妻反目。象曰：夫 妻反目，不能正室也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>有孚，血去惕出，無咎。象曰：有孚惕出，上合志也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>有孚攣如，富以其鄰。象曰：有孚攣如，不獨富也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>既雨既處，尚德載，婦貞厲。月幾望，君子徵兇。象曰：既雨既處，德積載也。君子徵兇，有所疑也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
